/* ==========================================================================
 *  crash_camera.c —— 崩溃体检用的"用户算法"（★ 测试夹具，不是模板）
 *  --------------------------------------------------------------------------
 *  这个文件【故意】写错。它存在的唯一理由：
 *
 *      templates/starter 里的模板代码是"温和"的 —— 线性数组、无越界、
 *      无递归。用它跑回归，22 条全绿，但【从不触发任何崩溃路径】。
 *      于是"用户代码把仿真进程搞死之后，插件表现如何"这件事，
 *      在引入 crash_probe.py 之前从来没有被验证过。
 *
 *  真实案例（2026-11-05，sgXD.c）：贪心八邻域搜线把路径点写进
 *  point m_path[800]，而中点插值是"外层 × 内层"两层循环，
 *  120 × 124 = 14880 次写入 —— 越界 14080 个元素。
 *  越界把 .data 段的 s_gray / s_w / s_h 一起踩坏，
 *  最后在 SCUT_EnvCopyOutput 里写到一个非法地址，
 *  进程以 0xC0000005（访问冲突）死掉，界面上什么都不显示。
 *
 *  这里刻意保留同样的病症（越界写 + 不设上限），但让它
 *  【一定】崩、且与输入图无关 —— 不依赖具体图集的边缘情况，
 *  这样这条测试在任何机器、任何图集上都会走到同一条路径。
 *
 *  ★ 为什么不用 `*(int*)0 = 1` 这种写法：
 *    那确实也崩，但它不是"用户会写出来的错"。
 *    用一个真实形态的越界（定长数组 + 无上限循环），
 *    测的才是"用户最容易踩到的那类崩溃"。
 * ========================================================================== */

#include "scut_sdk.h"

/* 定长数组，8 个元素 —— 模拟"路径点只开了一点点"。
 * 真实工程里这类数组常常是 800，而搜索循环没有上限。 */
static int s_path_x[8];
static int s_path_y[8];

int g_path_len = 0;

unsigned char g_binary[SCUT_IMAGE_H][SCUT_IMAGE_W];

void crash_init(void)
{
    int i;
    for (i = 0; i < 8; i++) {
        s_path_x[i] = 0;
        s_path_y[i] = 0;
    }
    g_path_len = 0;
}

void crash_process(void)
{
    int x, y;
    int pass;
    int n = 0;
    /* ★ 帧计数器：前 1 帧【正常】，从第 2 帧开始踩内存。
     *
     *  为什么必须是"先正常、后崩"而不是第 1 帧就崩：
     *  这条测试要验证的是【崩溃前后的对比】——
     *  "崩溃前确实出过帧" / "崩溃后能恢复"。若第 1 帧就死，
     *  就没有"正常"这个基准，测试只能看到一片黑，
     *  分不清是"崩溃了"还是"从来没跑起来"，判据也就没有意义了。
     *  真实场景正是这样：算法跑了几张图才把数组写满。 */
    static int s_frame_no = 0;
    s_frame_no++;

    /* --- 1) 正常的二值化，让这个算法"看起来是干活的" --- */
    for (y = 0; y < SCUT_IMAGE_H; y++) {
        for (x = 0; x < SCUT_IMAGE_W; x++) {
            g_binary[y][x] = (mt9v03x_image[y][x] > 128) ? 255 : 0;
        }
    }

    if (s_frame_no <= 1) {
        g_path_len = 0;
        return;                 /* 第 1 帧：一切正常，正常出图 */
    }

    /* --- 2) ★ 越界：8 个元素的数组，写几百万次 ---
     *
     *  两层循环模拟"搜线搜索没有收敛上限"：
     *  外层是搜索轮次，内层是逐像素推进，而写指针 n 只增不减，也没有
     *  if (n < 8) 的保护。真实算法里这个 n 就是 m_len / l_len。
     *
     *  ★ 为什么是 200 轮而不是 1 轮：实测只跑 1 轮（22560 次写入、
     *    约 90 KB）时，越界范围还落在同一个 PE 段内，
     *    【不崩但把全局变量踩坏】—— 表现为图集路径变成乱码、
     *    变量面板数字错乱，进程却正常退出（rc=0）。
     *    这类"静默踩坏"比崩溃更难查，但作为回归夹具它不稳定：
     *    段布局一变结论就变。所以这里写够远（约 18 MB），
     *    确保一定踩到未映射页 → 稳定复现 0xC0000005。
     *
     *    附带的好处：它同时证明了另一件事 ——
     *    越界【不一定】当场崩，可能只是悄悄改掉别的变量。
     *    这正是为什么插件必须把"进程异常终止"说清楚，
     *    也是为什么崩溃不能靠用户自己看画面发现。 */
    for (pass = 0; pass < 200; pass++) {
        for (y = 0; y < SCUT_IMAGE_H; y++) {
            for (x = 0; x < SCUT_IMAGE_W; x++) {
                s_path_x[n] = x;        /* ★ 没有 if (n < 8) 的保护 */
                s_path_y[n] = y;
                n++;
            }
        }
    }
    g_path_len = n;
}

void crash_draw(void)
{
    /* 走到这里之前进程应该已经死了。
     * 留一个能跑的实现，是为了让"没崩"这件事本身可观测 ——
     * 万一哪天越界不再崩（比如编译器把数组挪到了可写的大页），
     * 至少算法还能正常出图，测试会明确报"没有崩溃可测"。 */
    SCUT_DrawText(2, 6, SCUT_COLOR_YELLOW, "path=%d", g_path_len);
}
